// Draws an evaluated frame onto a 2D canvas. Only type-level DOM usage here;
// the context is constructed by the webview.

import type { EvaluatedBox, EvaluatedFrame } from "./frameEvaluator";
import type { CtxOutputData } from "./ctxBindings";
import type { DisplayMode, Rgba } from "../shared/sceneSchema";
import { fontSizePixels, strokeLineWidthsPixels } from "./renderUnits";
import {
  computeGradientLine,
  makeFourGradientBands,
  type GradientBand,
  type GradientBounds,
  type GradientLine,
} from "./gradient";
import { transformedPathBounds } from "./parts";
import { identity, invert, multiply, transformPoint, translation, type Mat2D } from "./transform";

const kCanvasBorderColor = "#3c3c3c";
const kIndexLabelColor = "rgba(255, 255, 255, 0.55)";
const kPartOutlineColor = "rgba(0, 0, 0, 0.35)";
const kPathCacheLimit = 2048;
const kCheckerCellSizePixels = 16;
const kCheckerContrastMix = 0.22;
const kWriteOnEpsilon = 1e-5;

interface FrameGradientDefinition {
  line: GradientLine;
  bands: readonly GradientBand[];
}

function cssColor(color: Rgba): string {
  const to255 = (value: number): number => Math.round(Math.min(Math.max(value, 0), 1) * 255);
  return `rgba(${to255(color.r)}, ${to255(color.g)}, ${to255(color.b)}, ${color.a})`;
}

function clampOpacity(opacity: number): number {
  return Math.min(Math.max(opacity, 0), 1);
}

// Path2D construction parses the SVG string; cache per path text. Glyph paths
// repeat across frames, so this hits almost always during playback.
const pathCache = new Map<string, Path2D>();

function cachedPath(pathData: string): Path2D {
  let path = pathCache.get(pathData);
  if (path === undefined) {
    if (pathCache.size >= kPathCacheLimit) {
      pathCache.clear();
    }
    path = new Path2D(pathData);
    pathCache.set(pathData, path);
  }
  return path;
}

export interface RenderOptions {
  displayMode: DisplayMode;
  showIndexLabels: boolean;
}

export function renderFrame(
  context: CanvasRenderingContext2D,
  frame: EvaluatedFrame,
  scale: number,
  options: RenderOptions,
): void {
  const fontSize = fontSizePixels(frame.canvasHeight);
  context.save();
  context.setTransform(1, 0, 0, 1, 0, 0);
  drawBackground(context, frame, scale);
  context.strokeStyle = kCanvasBorderColor;
  context.lineWidth = 1;
  context.strokeRect(0.5, 0.5, frame.canvasWidth * scale - 1, frame.canvasHeight * scale - 1);
  const gradient = makeFrameGradient(frame);
  const backgroundColor = { ...frame.backgroundColor, a: 1 };
  const strokeGapColor = frame.checkerboardBackground
    ? cssColor(contrastingCheckerColor(backgroundColor, kCheckerContrastMix / 2))
    : cssColor(backgroundColor);

  const visibleParts = writeOnVisibleParts(
    frame.parts,
    frame.characters.length,
    frame.scriptOutputValues?.output,
  );
  const orderedParts = frame.projection3D
    ? [...visibleParts].sort((first, second) => (second.projectionDepth ?? 0) - (first.projectionDepth ?? 0))
    : visibleParts;
  // Mirrors Native's per-part shadow gate (isShadowPass && !shadowDraw_ && !useIndividualShadowColor_
  // skips a part): the global toggle alone would miss a part whose own (or its character's)
  // individual shadow color is on while the global shadow is off. Spaces never cast shadows; at
  // most they show the show-spaces frame.
  for (const part of orderedParts.filter(
    (candidate) => candidate.isSpace !== true && (frame.shadowEnabled || candidate.hasIndividualShadow),
  )) {
    if (frame.projection3D) {
      drawProjectedShadow(context, part, scale, frame.shadowOffsetX, frame.shadowOffsetY, options.displayMode);
    } else if (options.displayMode === "glyph" && part.pathData !== undefined) {
      drawOutlineShadow(context, part, scale, frame.shadowOffsetX, frame.shadowOffsetY);
    } else {
      drawBoxShadow(context, part, scale, frame.shadowOffsetX, frame.shadowOffsetY);
    }
  }
  drawBoundingBox(context, frame, scale, fontSize);
  for (const part of orderedParts) {
    if (frame.projection3D) {
      drawProjectedOutline(
        context,
        part,
        scale,
        fontSize,
        gradient,
        options.displayMode,
        strokeGapColor,
        frame.showSpaces,
        frame.spaceColor,
      );
    } else if (options.displayMode === "glyph" && part.pathData !== undefined) {
      drawOutline(context, part, scale, fontSize, gradient, strokeGapColor);
    } else {
      drawBox(
        context,
        part,
        scale,
        fontSize,
        gradient,
        strokeGapColor,
        frame.showSpaces,
        frame.spaceColor,
      );
    }
  }
  if (options.showIndexLabels) {
    for (const character of frame.characters) {
      drawIndexLabel(context, character, scale);
    }
  }
  context.restore();
}

type WriteOnParameters = Pick<
  CtxOutputData,
  "write_on_mode" | "write_on_start" | "write_on_end"
>;

export function writeOnVisibleParts(
  parts: readonly EvaluatedBox[],
  characterCount: number,
  parameters: WriteOnParameters | undefined,
): readonly EvaluatedBox[] {
  let result = parts;
  if (parameters !== undefined) {
    const writeOnActive =
      parameters.write_on_start > kWriteOnEpsilon ||
      parameters.write_on_end < 1 - kWriteOnEpsilon;
    if (writeOnActive) {
      if (parameters.write_on_mode === "character") {
        const startPosition = Math.min(
          Math.max(Math.floor(parameters.write_on_start * characterCount) + 1, 1),
          characterCount + 1,
        );
        const endPosition = Math.min(
          Math.max(Math.ceil(parameters.write_on_end * characterCount), 0),
          characterCount,
        );
        result = parts.filter(
          (part) => part.characterIndex >= startPosition && part.characterIndex <= endPosition,
        );
      } else {
        const startPosition = Math.min(
          Math.max(Math.floor(parameters.write_on_start * parts.length) + 1, 1),
          parts.length + 1,
        );
        const endPosition = Math.min(
          Math.max(Math.ceil(parameters.write_on_end * parts.length), 0),
          parts.length,
        );
        result = parts.filter((_, index) => {
          const partPosition = index + 1;
          return partPosition >= startPosition && partPosition <= endPosition;
        });
      }
    }
  }
  return result;
}

function drawBoundingBox(
  context: CanvasRenderingContext2D,
  frame: EvaluatedFrame,
  scale: number,
  fontSize: number,
): void {
  const parameters = frame.scriptOutputValues?.boundingBox;
  const renderMode = frame.scriptOutputValues?.output.render_mode;
  const bounds = transformedPartBounds(frame.parts);
  if (parameters === undefined || !parameters.enabled || renderMode !== "default" || bounds === undefined) {
    return;
  }

  const parameterUnitPixels = fontSize / 100;
  const marginX = parameters.margin_x * parameterUnitPixels;
  const marginY = parameters.margin_y * parameterUnitPixels;
  const baseBounds = {
    minX: bounds.minX - marginX,
    minY: bounds.minY - marginY,
    maxX: bounds.maxX + marginX,
    maxY: bounds.maxY + marginY,
  };
  context.save();
  context.setTransform(scale, 0, 0, scale, 0, 0);
  context.globalAlpha = clampOpacity(frame.scriptOutputValues?.global?.opacity ?? 1);
  if (parameters.fill_enabled) {
    const fillBounds = offsetBounds(
      baseBounds,
      parameters.fill_offset_x * parameterUnitPixels,
      parameters.fill_offset_y * parameterUnitPixels,
    );
    context.fillStyle = cssColor({
      ...parameters.fill_color,
      a: parameters.fill_color.a * parameters.fill_opacity,
    });
    addBoundingBoxPath(context, fillBounds, parameters.corner_radius * parameterUnitPixels);
    context.fill();
  }

  const strokeBounds = offsetBounds(
    baseBounds,
    parameters.stroke_offset_x * parameterUnitPixels,
    parameters.stroke_offset_y * parameterUnitPixels,
  );
  context.strokeStyle = cssColor(parameters.color);
  context.lineWidth = parameters.width * parameterUnitPixels;
  context.lineCap = canvasLineCap(parameters.start_cap, parameters.end_cap);
  drawBoundingBoxStroke(context, strokeBounds, parameters.corner_radius * parameterUnitPixels, {
    top: parameters.draw_top,
    bottom: parameters.draw_bottom,
    left: parameters.draw_left,
    right: parameters.draw_right,
  });
  context.restore();
}

function addBoundingBoxPath(
  context: CanvasRenderingContext2D,
  bounds: GradientBounds,
  cornerRadius: number,
): void {
  const width = bounds.maxX - bounds.minX;
  const height = bounds.maxY - bounds.minY;
  const radius = Math.min(Math.max(cornerRadius, 0), width / 2, height / 2);
  context.beginPath();
  if (radius > 0) {
    context.roundRect(bounds.minX, bounds.minY, width, height, radius);
  } else {
    context.rect(bounds.minX, bounds.minY, width, height);
  }
}

interface BoundingBoxEdges {
  top: boolean;
  bottom: boolean;
  left: boolean;
  right: boolean;
}

function drawBoundingBoxStroke(
  context: CanvasRenderingContext2D,
  bounds: GradientBounds,
  cornerRadius: number,
  edges: BoundingBoxEdges,
): void {
  const allEdges = edges.top && edges.bottom && edges.left && edges.right;
  if (allEdges) {
    addBoundingBoxPath(context, bounds, cornerRadius);
  } else {
    context.beginPath();
    if (edges.left) {
      context.moveTo(bounds.minX, bounds.minY);
      context.lineTo(bounds.minX, bounds.maxY);
    }
    if (edges.bottom) {
      context.moveTo(bounds.minX, bounds.maxY);
      context.lineTo(bounds.maxX, bounds.maxY);
    }
    if (edges.right) {
      context.moveTo(bounds.maxX, bounds.maxY);
      context.lineTo(bounds.maxX, bounds.minY);
    }
    if (edges.top) {
      context.moveTo(bounds.maxX, bounds.minY);
      context.lineTo(bounds.minX, bounds.minY);
    }
  }
  context.stroke();
}

function offsetBounds(bounds: GradientBounds, offsetX: number, offsetY: number): GradientBounds {
  return {
    minX: bounds.minX + offsetX,
    minY: bounds.minY + offsetY,
    maxX: bounds.maxX + offsetX,
    maxY: bounds.maxY + offsetY,
  };
}

function canvasLineCap(startCap: string, endCap: string): CanvasLineCap {
  const normalizedStart = normalizeCanvasLineCap(startCap);
  const normalizedEnd = normalizeCanvasLineCap(endCap);
  return normalizedStart === normalizedEnd ? normalizedStart : "butt";
}

function normalizeCanvasLineCap(cap: string): CanvasLineCap {
  let result: CanvasLineCap = "butt";
  if (cap === "square") {
    result = "square";
  } else if (cap === "round" || cap === "round_rev") {
    result = "round";
  }
  return result;
}

function drawBackground(
  context: CanvasRenderingContext2D,
  frame: EvaluatedFrame,
  scale: number,
): void {
  const width = frame.canvasWidth * scale;
  const height = frame.canvasHeight * scale;
  context.clearRect(0, 0, width, height);
  const backgroundColor = { ...frame.backgroundColor, a: 1 };
  if (frame.checkerboardBackground) {
    const baseColor = cssColor(backgroundColor);
    const alternateColor = cssColor(
      contrastingCheckerColor(backgroundColor, kCheckerContrastMix),
    );
    for (let y = 0; y < height; y += kCheckerCellSizePixels) {
      for (let x = 0; x < width; x += kCheckerCellSizePixels) {
        const column = Math.floor(x / kCheckerCellSizePixels);
        const row = Math.floor(y / kCheckerCellSizePixels);
        context.fillStyle = (column + row) % 2 === 0 ? baseColor : alternateColor;
        context.fillRect(x, y, kCheckerCellSizePixels, kCheckerCellSizePixels);
      }
    }
  } else {
    context.fillStyle = cssColor(backgroundColor);
    context.fillRect(0, 0, width, height);
  }
}

function contrastingCheckerColor(color: Rgba, mix: number): Rgba {
  const luminance = 0.2126 * color.r + 0.7152 * color.g + 0.0722 * color.b;
  const target = luminance >= 0.5 ? 0 : 1;
  const mixChannel = (channel: number): number => channel + (target - channel) * mix;
  return {
    r: mixChannel(color.r),
    g: mixChannel(color.g),
    b: mixChannel(color.b),
    a: color.a,
  };
}

function applyBoxTransform(
  context: CanvasRenderingContext2D,
  box: EvaluatedBox,
  scale: number,
  offsetX = 0,
  offsetY = 0,
): void {
  const { matrix } = box;
  context.setTransform(
    matrix.a * scale,
    matrix.b * scale,
    matrix.c * scale,
    matrix.d * scale,
    (matrix.e + offsetX) * scale,
    (matrix.f + offsetY) * scale,
  );
}

function drawBox(
  context: CanvasRenderingContext2D,
  box: EvaluatedBox,
  scale: number,
  fontSize: number,
  gradient: FrameGradientDefinition | undefined,
  strokeGapColor: string,
  showSpaces: boolean,
  spaceColor: Rgba,
): void {
  context.save();
  applyBoxTransform(context, box, scale);
  context.globalAlpha = clampOpacity(box.opacity);
  const x = box.centerX - box.width / 2;
  const y = box.centerY - box.height / 2;
  if (box.isSpace === true) {
    if (showSpaces) {
      context.strokeStyle = cssColor(spaceColor);
      context.lineWidth = 1 / scale;
      context.strokeRect(x, y, box.width, box.height);
    }
  } else {
    if (box.strokeWidth > 0) {
      const lineWidths = strokeLineWidthsPixels(box.strokeWidth, box.strokeGap, fontSize);
      context.strokeStyle = cssColor(box.strokeColor);
      context.lineWidth = lineWidths.outer;
      context.strokeRect(x, y, box.width, box.height);
      if (lineWidths.gap > 0) {
        context.strokeStyle = strokeGapColor;
        context.lineWidth = lineWidths.gap;
        context.strokeRect(x, y, box.width, box.height);
      }
    }
    const localGradient = box.useGradientFill
      ? makeLocalGradient(context, gradient, box.matrix)
      : undefined;
    context.fillStyle = localGradient ?? cssColor(box.fillColor);
    context.fillRect(x, y, box.width, box.height);
    if (box.strokeWidth <= 0) {
      context.strokeStyle = kPartOutlineColor;
      context.lineWidth = 1 / scale;
      context.strokeRect(x, y, box.width, box.height);
    }
  }
  context.restore();
}

function drawOutline(
  context: CanvasRenderingContext2D,
  box: EvaluatedBox,
  scale: number,
  fontSize: number,
  gradient: FrameGradientDefinition | undefined,
  strokeGapColor: string,
): void {
  if (box.pathData === undefined || box.originX === undefined || box.originY === undefined) {
    return;
  }
  context.save();
  applyBoxTransform(context, box, scale);
  context.globalAlpha = clampOpacity(box.opacity);
  context.translate(box.originX, box.originY);
  if (box.clipRect !== undefined) {
    context.beginPath();
    context.rect(box.clipRect.x, box.clipRect.y, box.clipRect.width, box.clipRect.height);
    context.clip();
  }
  const path = cachedPath(box.pathData);
  if (box.strokeWidth > 0) {
    const lineWidths = strokeLineWidthsPixels(box.strokeWidth, box.strokeGap, fontSize);
    context.strokeStyle = cssColor(box.strokeColor);
    context.lineWidth = lineWidths.outer;
    context.stroke(path);
    if (lineWidths.gap > 0) {
      context.strokeStyle = strokeGapColor;
      context.lineWidth = lineWidths.gap;
      context.stroke(path);
    }
  }
  const pathMatrix = multiply(box.matrix, translation(box.originX, box.originY));
  const localGradient = box.useGradientFill
    ? makeLocalGradient(context, gradient, pathMatrix)
    : undefined;
  context.fillStyle = localGradient ?? cssColor(box.fillColor);
  context.fill(path);
  context.restore();
}

function drawProjectedOutline(
  context: CanvasRenderingContext2D,
  box: EvaluatedBox,
  scale: number,
  fontSize: number,
  gradient: FrameGradientDefinition | undefined,
  displayMode: DisplayMode,
  strokeGapColor: string,
  showSpaces: boolean,
  spaceColor: Rgba,
): void {
  const pathData = displayMode === "glyph" && box.projectedPathData !== undefined
    ? box.projectedPathData
    : box.projectedBoxPathData;
  if (pathData === undefined || pathData.length === 0) {
    return;
  }
  const isSpace = box.isSpace === true;
  if (isSpace && !showSpaces) {
    return;
  }
  context.save();
  context.setTransform(scale, 0, 0, scale, 0, 0);
  context.globalAlpha = clampOpacity(box.opacity);
  if (displayMode === "glyph" && box.projectedClipPathData !== undefined) {
    context.clip(new Path2D(box.projectedClipPathData));
  }
  // Projected path text changes on every animated frame, so retaining it in
  // the static glyph cache would only create cache churn.
  const path = new Path2D(pathData);
  if (isSpace) {
    context.strokeStyle = cssColor(spaceColor);
    context.lineWidth = 1 / scale;
    context.stroke(path);
  } else {
    if (box.strokeWidth > 0) {
      const lineWidths = strokeLineWidthsPixels(box.strokeWidth, box.strokeGap, fontSize);
      context.strokeStyle = cssColor(box.strokeColor);
      context.lineWidth = lineWidths.outer;
      context.stroke(path);
      if (lineWidths.gap > 0) {
        context.strokeStyle = strokeGapColor;
        context.lineWidth = lineWidths.gap;
        context.stroke(path);
      }
    }
    const localGradient = box.useGradientFill
      ? makeLocalGradient(context, gradient, identity())
      : undefined;
    context.fillStyle = localGradient ?? cssColor(box.fillColor);
    context.fill(path);
  }
  context.restore();
}

function makeFrameGradient(frame: EvaluatedFrame): FrameGradientDefinition | undefined {
  const bounds = frame.gradient.enabled ? transformedPartBounds(frame.parts) : undefined;
  let result: FrameGradientDefinition | undefined;
  if (bounds !== undefined) {
    const line = computeGradientLine(bounds, frame.gradient);
    const deltaX = line.endX - line.startX;
    const deltaY = line.endY - line.startY;
    if (Math.hypot(deltaX, deltaY) > Number.EPSILON) {
      result = {
        line,
        bands: makeFourGradientBands(
          frame.gradient.startColor,
          frame.gradient.endColor,
          frame.gradient.midpoint,
        ),
      };
    }
  }
  return result;
}

function makeLocalGradient(
  context: CanvasRenderingContext2D,
  gradient: FrameGradientDefinition | undefined,
  localToCanvas: Mat2D,
): CanvasGradient | undefined {
  const line = gradient === undefined
    ? undefined
    : gradientLineInLocalSpace(gradient.line, localToCanvas);
  let result: CanvasGradient | undefined;
  if (gradient !== undefined && line !== undefined) {
    result = context.createLinearGradient(line.startX, line.startY, line.endX, line.endY);
    for (const band of gradient.bands) {
      const color = cssColor(band.color);
      result.addColorStop(band.start, color);
      result.addColorStop(band.end, color);
    }
  }
  return result;
}

export function gradientLineInLocalSpace(
  line: GradientLine,
  localToCanvas: Mat2D,
): GradientLine | undefined {
  const canvasToLocal = invert(localToCanvas);
  let result: GradientLine | undefined;
  if (canvasToLocal !== undefined) {
    const start = transformPoint(canvasToLocal, line.startX, line.startY);
    const end = transformPoint(canvasToLocal, line.endX, line.endY);
    result = { startX: start.x, startY: start.y, endX: end.x, endY: end.y };
  }
  return result;
}

export function transformedPartBounds(parts: readonly EvaluatedBox[]): GradientBounds | undefined {
  let result: GradientBounds | undefined;
  for (const part of parts) {
    const partBounds = visiblePartBounds(part);
    if (partBounds !== undefined) {
      result = unionBounds(result, partBounds);
    }
  }
  return result;
}

function visiblePartBounds(part: EvaluatedBox): GradientBounds | undefined {
  let result: GradientBounds | undefined;
  const projectedBoundsPath = part.projectedPathData ?? part.projectedBoxPathData;
  if (projectedBoundsPath !== undefined) {
    result = transformedPathBounds(projectedBoundsPath, identity());
    if (result !== undefined && part.projectedClipPathData !== undefined) {
      const clipBounds = transformedPathBounds(part.projectedClipPathData, identity());
      result = clipBounds === undefined ? result : intersectBounds(result, clipBounds);
    }
  } else if (part.pathData !== undefined && part.originX !== undefined && part.originY !== undefined) {
    const pathMatrix = multiply(part.matrix, translation(part.originX, part.originY));
    if (part.clipRect === undefined) {
      result = transformedPathBounds(part.pathData, pathMatrix);
    } else {
      const localPathBounds = transformedPathBounds(part.pathData, identity());
      const clippedBounds = localPathBounds === undefined
        ? undefined
        : intersectBounds(localPathBounds, {
          minX: part.clipRect.x,
          minY: part.clipRect.y,
          maxX: part.clipRect.x + part.clipRect.width,
          maxY: part.clipRect.y + part.clipRect.height,
        });
      if (clippedBounds !== undefined) {
        result = transformRectangleBounds(clippedBounds, pathMatrix);
      }
    }
  } else {
    result = transformRectangleBounds({
      minX: part.centerX - part.width / 2,
      minY: part.centerY - part.height / 2,
      maxX: part.centerX + part.width / 2,
      maxY: part.centerY + part.height / 2,
    }, part.matrix);
  }
  return result;
}

function drawProjectedShadow(
  context: CanvasRenderingContext2D,
  box: EvaluatedBox,
  scale: number,
  offsetX: number,
  offsetY: number,
  displayMode: DisplayMode,
): void {
  const usePlaneShift = box.projectedShadowPathData !== undefined || box.projectedShadowBoxPathData !== undefined;
  const pathData = displayMode === "glyph"
    ? (usePlaneShift ? box.projectedShadowPathData : box.projectedPathData)
    : (usePlaneShift ? box.projectedShadowBoxPathData : box.projectedBoxPathData);
  const clipPathData = displayMode === "glyph"
    ? (usePlaneShift ? box.projectedShadowClipPathData ?? box.projectedClipPathData : box.projectedClipPathData)
    : undefined;
  if (pathData !== undefined && pathData.length > 0) {
    context.save();
    if (usePlaneShift) {
      context.setTransform(scale, 0, 0, scale, 0, 0);
    } else {
      context.setTransform(scale, 0, 0, scale, offsetX * scale, offsetY * scale);
    }
    context.globalAlpha = clampOpacity(box.opacity);
    if (clipPathData !== undefined) {
      context.clip(new Path2D(clipPathData));
    }
    context.fillStyle = cssColor(box.shadowColor);
    context.fill(new Path2D(pathData));
    context.restore();
  }
}

function transformRectangleBounds(bounds: GradientBounds, matrix: Mat2D): GradientBounds {
  const corners = [
    transformPoint(matrix, bounds.minX, bounds.minY),
    transformPoint(matrix, bounds.maxX, bounds.minY),
    transformPoint(matrix, bounds.minX, bounds.maxY),
    transformPoint(matrix, bounds.maxX, bounds.maxY),
  ];
  return {
    minX: Math.min(...corners.map((corner) => corner.x)),
    minY: Math.min(...corners.map((corner) => corner.y)),
    maxX: Math.max(...corners.map((corner) => corner.x)),
    maxY: Math.max(...corners.map((corner) => corner.y)),
  };
}

function intersectBounds(
  first: GradientBounds,
  second: GradientBounds,
): GradientBounds | undefined {
  const intersection = {
    minX: Math.max(first.minX, second.minX),
    minY: Math.max(first.minY, second.minY),
    maxX: Math.min(first.maxX, second.maxX),
    maxY: Math.min(first.maxY, second.maxY),
  };
  return intersection.minX <= intersection.maxX && intersection.minY <= intersection.maxY
    ? intersection
    : undefined;
}

function unionBounds(
  first: GradientBounds | undefined,
  second: GradientBounds,
): GradientBounds {
  return first === undefined
    ? { ...second }
    : {
      minX: Math.min(first.minX, second.minX),
      minY: Math.min(first.minY, second.minY),
      maxX: Math.max(first.maxX, second.maxX),
      maxY: Math.max(first.maxY, second.maxY),
    };
}

function drawBoxShadow(
  context: CanvasRenderingContext2D,
  box: EvaluatedBox,
  scale: number,
  offsetX: number,
  offsetY: number,
): void {
  context.save();
  applyBoxTransform(context, box, scale, offsetX, offsetY);
  context.globalAlpha = clampOpacity(box.opacity);
  context.fillStyle = cssColor(box.shadowColor);
  context.fillRect(box.centerX - box.width / 2, box.centerY - box.height / 2, box.width, box.height);
  context.restore();
}

function drawOutlineShadow(
  context: CanvasRenderingContext2D,
  box: EvaluatedBox,
  scale: number,
  offsetX: number,
  offsetY: number,
): void {
  if (box.pathData !== undefined && box.originX !== undefined && box.originY !== undefined) {
    context.save();
    applyBoxTransform(context, box, scale, offsetX, offsetY);
    context.globalAlpha = clampOpacity(box.opacity);
    context.translate(box.originX, box.originY);
    if (box.clipRect !== undefined) {
      context.beginPath();
      context.rect(box.clipRect.x, box.clipRect.y, box.clipRect.width, box.clipRect.height);
      context.clip();
    }
    context.fillStyle = cssColor(box.shadowColor);
    context.fill(cachedPath(box.pathData));
    context.restore();
  }
}

function drawIndexLabel(context: CanvasRenderingContext2D, box: EvaluatedBox, scale: number): void {
  const position = box.projectedCenterX !== undefined && box.projectedCenterY !== undefined
    ? { x: box.projectedCenterX, y: box.projectedCenterY }
    : {
      x: box.matrix.a * box.centerX + box.matrix.c * box.centerY + box.matrix.e,
      y: box.matrix.b * box.centerX + box.matrix.d * box.centerY + box.matrix.f,
    };
  context.setTransform(1, 0, 0, 1, 0, 0);
  context.fillStyle = kIndexLabelColor;
  context.font = "11px sans-serif";
  context.textAlign = "center";
  context.textBaseline = "middle";
  const label = box.text !== undefined ? `${box.index}:${box.text}` : String(box.index);
  const labelOffset = box.projectedCenterY === undefined ? box.height * 0.75 : 18;
  context.fillText(label, position.x * scale, (position.y - labelOffset) * scale);
}
