// Approximates the host plugin's per-part glyph decomposition from an SVG
// path string (absolute M/L/Q/C/Z commands, as produced by HarfBuzz): split
// into contours at each M, classify solids vs holes by winding orientation,
// and attach each hole to the smallest enclosing solid. The grouping is a
// heuristic — scripts must not depend on part counts or shapes, so matching
// the host's exact decomposition is not required.

import type { Mat2D } from "./transform";
import { identity, transformPoint } from "./transform";

export interface Contour {
  pathData: string;
  // Signed area of the contour polygon (endpoint sampling); the sign encodes
  // winding orientation.
  area: number;
  centroidX: number;
  centroidY: number;
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
}

export interface GlyphPart {
  // Solid contour followed by its holes, which carry the opposite winding so
  // that a non-zero fill cuts them out (matching the host plugin's Blend2D fill).
  pathData: string;
  centerX: number;
  centerY: number;
  width: number;
  height: number;
}

export interface PathBounds {
  centerX: number;
  centerY: number;
  width: number;
  height: number;
}

export interface AxisAlignedBounds {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
}

export interface FlattenedSubpath {
  points: Array<{ x: number; y: number }>;
  closed: boolean;
}

const kCommandPattern = /([MLQCZ])([^MLQCZ]*)/g;
// SVG allows "10-5" (minus as separator), so numbers must be extracted with a
// pattern rather than split on whitespace/commas.
const kNumberPattern = /-?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?/g;
const kParsedPathCacheLimit = 2048;

interface ParsedPathCommand {
  command: string;
  values: number[];
}

const parsedPathCache = new Map<string, readonly ParsedPathCommand[]>();

function parsePoints(argumentText: string): number[] {
  return (argumentText.match(kNumberPattern) ?? []).map(Number);
}

export function splitContours(pathData: string): Contour[] {
  const contours: Contour[] = [];
  let currentCommands: string[] = [];
  let currentPoints: Array<{ x: number; y: number }> = [];

  const flush = (): void => {
    if (currentCommands.length > 0 && currentPoints.length >= 3) {
      contours.push(buildContour(currentCommands.join(""), currentPoints));
    }
    currentCommands = [];
    currentPoints = [];
  };

  for (const { command, values } of parsedPath(pathData)) {
    if (command === "M") {
      flush();
    }
    currentCommands.push(command + values.join(","));
    // Track command endpoints (and curve control points, which only tighten
    // the bounding box) for area/centroid/bbox estimation.
    for (let index = 0; index + 1 < values.length; index += 2) {
      currentPoints.push({ x: values[index], y: values[index + 1] });
    }
  }
  flush();
  return contours;
}

export function pathBounds(pathData: string): PathBounds | undefined {
  const bounds = transformedPathBounds(pathData, identity());
  let result: PathBounds | undefined;
  if (bounds !== undefined) {
    result = {
      centerX: (bounds.minX + bounds.maxX) / 2,
      centerY: (bounds.minY + bounds.maxY) / 2,
      width: bounds.maxX - bounds.minX,
      height: bounds.maxY - bounds.minY,
    };
  }
  return result;
}

// Mirrors Blend2D's transform-then-get_bounding_box flow used by the host.
// Affine-transformed Bézier control points still describe a Bézier curve, so
// evaluating their derivative roots yields its exact axis-aligned bounds.
export function transformedPathBounds(
  pathData: string,
  matrix: Mat2D,
): AxisAlignedBounds | undefined {
  let bounds: AxisAlignedBounds | undefined;
  let currentPoint: Point | undefined;
  let subpathStart: Point | undefined;

  const includePoint = (point: Point): void => {
    if (bounds === undefined) {
      bounds = { minX: point.x, minY: point.y, maxX: point.x, maxY: point.y };
    } else {
      bounds.minX = Math.min(bounds.minX, point.x);
      bounds.minY = Math.min(bounds.minY, point.y);
      bounds.maxX = Math.max(bounds.maxX, point.x);
      bounds.maxY = Math.max(bounds.maxY, point.y);
    }
  };

  const mappedPoint = (x: number, y: number): Point => transformPoint(matrix, x, y);
  for (const { command, values } of parsedPath(pathData)) {
    if (command === "M") {
      for (let index = 0; index + 1 < values.length; index += 2) {
        const point = mappedPoint(values[index], values[index + 1]);
        if (index === 0) {
          subpathStart = point;
        } else if (currentPoint !== undefined) {
          includeLine(currentPoint, point, includePoint);
        }
        currentPoint = point;
      }
    } else if (command === "L") {
      for (let index = 0; currentPoint !== undefined && index + 1 < values.length; index += 2) {
        const endPoint = mappedPoint(values[index], values[index + 1]);
        includeLine(currentPoint, endPoint, includePoint);
        currentPoint = endPoint;
      }
    } else if (command === "Q") {
      for (let index = 0; currentPoint !== undefined && index + 3 < values.length; index += 4) {
        const controlPoint = mappedPoint(values[index], values[index + 1]);
        const endPoint = mappedPoint(values[index + 2], values[index + 3]);
        includeQuadratic(currentPoint, controlPoint, endPoint, includePoint);
        currentPoint = endPoint;
      }
    } else if (command === "C") {
      for (let index = 0; currentPoint !== undefined && index + 5 < values.length; index += 6) {
        const firstControl = mappedPoint(values[index], values[index + 1]);
        const secondControl = mappedPoint(values[index + 2], values[index + 3]);
        const endPoint = mappedPoint(values[index + 4], values[index + 5]);
        includeCubic(currentPoint, firstControl, secondControl, endPoint, includePoint);
        currentPoint = endPoint;
      }
    } else if (command === "Z" && currentPoint !== undefined && subpathStart !== undefined) {
      includeLine(currentPoint, subpathStart, includePoint);
      currentPoint = subpathStart;
    }
  }
  return bounds;
}

function parsedPath(pathData: string): readonly ParsedPathCommand[] {
  let result = parsedPathCache.get(pathData);
  if (result === undefined) {
    if (parsedPathCache.size >= kParsedPathCacheLimit) {
      parsedPathCache.clear();
    }
    result = [...pathData.matchAll(kCommandPattern)].map((match) => ({
      command: match[1],
      values: parsePoints(match[2]),
    }));
    parsedPathCache.set(pathData, result);
  }
  return result;
}

// Perspective projection cannot be represented by Canvas' affine Path2D
// transform. A deliberately small, fixed number of segments keeps the 3D
// preview responsive while preserving the overall glyph silhouette.
export function flattenPath(pathData: string, curveSegments = 8): FlattenedSubpath[] {
  const segmentCount = Math.max(Math.round(curveSegments), 1);
  const result: FlattenedSubpath[] = [];
  let points: Array<{ x: number; y: number }> = [];
  let currentPoint: Point | undefined;

  const flush = (closed: boolean): void => {
    if (points.length > 1) {
      result.push({ points, closed });
    }
    points = [];
    currentPoint = undefined;
  };

  for (const { command, values } of parsedPath(pathData)) {
    if (command === "M") {
      flush(false);
      for (let index = 0; index + 1 < values.length; index += 2) {
        currentPoint = { x: values[index], y: values[index + 1] };
        points.push(currentPoint);
      }
    } else if (command === "L") {
      for (let index = 0; index + 1 < values.length; index += 2) {
        currentPoint = { x: values[index], y: values[index + 1] };
        points.push(currentPoint);
      }
    } else if (command === "Q" && currentPoint !== undefined) {
      for (let index = 0; index + 3 < values.length; index += 4) {
        const start = currentPoint;
        const control = { x: values[index], y: values[index + 1] };
        const end = { x: values[index + 2], y: values[index + 3] };
        for (let segment = 1; segment <= segmentCount; segment += 1) {
          const amount = segment / segmentCount;
          points.push({
            x: quadraticValue(start.x, control.x, end.x, amount),
            y: quadraticValue(start.y, control.y, end.y, amount),
          });
        }
        currentPoint = end;
      }
    } else if (command === "C" && currentPoint !== undefined) {
      for (let index = 0; index + 5 < values.length; index += 6) {
        const start = currentPoint;
        const firstControl = { x: values[index], y: values[index + 1] };
        const secondControl = { x: values[index + 2], y: values[index + 3] };
        const end = { x: values[index + 4], y: values[index + 5] };
        for (let segment = 1; segment <= segmentCount; segment += 1) {
          const amount = segment / segmentCount;
          points.push({
            x: cubicValue(start.x, firstControl.x, secondControl.x, end.x, amount),
            y: cubicValue(start.y, firstControl.y, secondControl.y, end.y, amount),
          });
        }
        currentPoint = end;
      }
    } else if (command === "Z") {
      flush(true);
    }
  }
  flush(false);
  return result;
}

interface Point {
  x: number;
  y: number;
}

type PointConsumer = (point: Point) => void;

const kCurveRootEpsilon = 1e-12;

function includeLine(start: Point, end: Point, includePoint: PointConsumer): void {
  includePoint(start);
  includePoint(end);
}

function includeQuadratic(
  start: Point,
  control: Point,
  end: Point,
  includePoint: PointConsumer,
): void {
  includePoint(start);
  includePoint(end);
  const roots = new Set<number>();
  addQuadraticExtremum(start.x, control.x, end.x, roots);
  addQuadraticExtremum(start.y, control.y, end.y, roots);
  for (const amount of roots) {
    includePoint({
      x: quadraticValue(start.x, control.x, end.x, amount),
      y: quadraticValue(start.y, control.y, end.y, amount),
    });
  }
}

function addQuadraticExtremum(
  start: number,
  control: number,
  end: number,
  roots: Set<number>,
): void {
  const denominator = start - 2 * control + end;
  if (Math.abs(denominator) > kCurveRootEpsilon) {
    addUnitRoot((start - control) / denominator, roots);
  }
}

function includeCubic(
  start: Point,
  firstControl: Point,
  secondControl: Point,
  end: Point,
  includePoint: PointConsumer,
): void {
  includePoint(start);
  includePoint(end);
  const roots = new Set<number>();
  addCubicExtrema(start.x, firstControl.x, secondControl.x, end.x, roots);
  addCubicExtrema(start.y, firstControl.y, secondControl.y, end.y, roots);
  for (const amount of roots) {
    includePoint({
      x: cubicValue(start.x, firstControl.x, secondControl.x, end.x, amount),
      y: cubicValue(start.y, firstControl.y, secondControl.y, end.y, amount),
    });
  }
}

function addCubicExtrema(
  start: number,
  firstControl: number,
  secondControl: number,
  end: number,
  roots: Set<number>,
): void {
  const quadratic = -start + 3 * firstControl - 3 * secondControl + end;
  const linear = 2 * (start - 2 * firstControl + secondControl);
  const constant = firstControl - start;
  if (Math.abs(quadratic) <= kCurveRootEpsilon) {
    if (Math.abs(linear) > kCurveRootEpsilon) {
      addUnitRoot(-constant / linear, roots);
    }
  } else {
    const discriminant = linear * linear - 4 * quadratic * constant;
    if (discriminant >= 0) {
      const squareRoot = Math.sqrt(discriminant);
      addUnitRoot((-linear + squareRoot) / (2 * quadratic), roots);
      addUnitRoot((-linear - squareRoot) / (2 * quadratic), roots);
    }
  }
}

function addUnitRoot(value: number, roots: Set<number>): void {
  if (value > 0 && value < 1) {
    roots.add(value);
  }
}

function quadraticValue(start: number, control: number, end: number, amount: number): number {
  const inverse = 1 - amount;
  return inverse * inverse * start + 2 * inverse * amount * control + amount * amount * end;
}

function cubicValue(
  start: number,
  firstControl: number,
  secondControl: number,
  end: number,
  amount: number,
): number {
  const inverse = 1 - amount;
  return inverse * inverse * inverse * start
    + 3 * inverse * inverse * amount * firstControl
    + 3 * inverse * amount * amount * secondControl
    + amount * amount * amount * end;
}

function buildContour(pathData: string, points: Array<{ x: number; y: number }>): Contour {
  let area = 0;
  let centroidX = 0;
  let centroidY = 0;
  let minX = Number.POSITIVE_INFINITY;
  let minY = Number.POSITIVE_INFINITY;
  let maxX = Number.NEGATIVE_INFINITY;
  let maxY = Number.NEGATIVE_INFINITY;
  for (const [index, point] of points.entries()) {
    const next = points[(index + 1) % points.length];
    area += point.x * next.y - next.x * point.y;
    centroidX += point.x;
    centroidY += point.y;
    minX = Math.min(minX, point.x);
    minY = Math.min(minY, point.y);
    maxX = Math.max(maxX, point.x);
    maxY = Math.max(maxY, point.y);
  }
  return {
    pathData,
    area: area / 2,
    centroidX: centroidX / points.length,
    centroidY: centroidY / points.length,
    minX,
    minY,
    maxX,
    maxY,
  };
}

function containsPoint(contour: Contour, x: number, y: number): boolean {
  return x >= contour.minX && x <= contour.maxX && y >= contour.minY && y <= contour.maxY;
}

function boundingArea(contour: Contour): number {
  return (contour.maxX - contour.minX) * (contour.maxY - contour.minY);
}

// Groups contours into pseudo parts: the orientation of the largest contour
// is taken as the "outer" (solid) winding; opposite-winding contours are
// holes and attach to the smallest solid whose bounding box contains their
// centroid.
export function approximateParts(pathData: string): GlyphPart[] {
  const contours = splitContours(pathData);
  const result: GlyphPart[] = [];
  if (contours.length > 0) {
    let largest = contours[0];
    for (const contour of contours) {
      if (Math.abs(contour.area) > Math.abs(largest.area)) {
        largest = contour;
      }
    }
    const outerSign = Math.sign(largest.area);
    const solids = contours.filter((contour) => Math.sign(contour.area) === outerSign);
    const holes = contours.filter((contour) => Math.sign(contour.area) !== outerSign);

    const holesBySolid = new Map<Contour, Contour[]>();
    for (const hole of holes) {
      let owner: Contour | undefined;
      for (const solid of solids) {
        if (containsPoint(solid, hole.centroidX, hole.centroidY)) {
          if (owner === undefined || boundingArea(solid) < boundingArea(owner)) {
            owner = solid;
          }
        }
      }
      if (owner === undefined && solids.length > 0) {
        owner = solids[0];
      }
      if (owner !== undefined) {
        const list = holesBySolid.get(owner) ?? [];
        list.push(hole);
        holesBySolid.set(owner, list);
      }
    }

    for (const solid of solids) {
      const attachedHoles = holesBySolid.get(solid) ?? [];
      let minX = solid.minX;
      let minY = solid.minY;
      let maxX = solid.maxX;
      let maxY = solid.maxY;
      for (const hole of attachedHoles) {
        minX = Math.min(minX, hole.minX);
        minY = Math.min(minY, hole.minY);
        maxX = Math.max(maxX, hole.maxX);
        maxY = Math.max(maxY, hole.maxY);
      }
      result.push({
        pathData: solid.pathData + attachedHoles.map((hole) => hole.pathData).join(""),
        centerX: (minX + maxX) / 2,
        centerY: (minY + maxY) / 2,
        width: Math.max(maxX - minX, 1e-6),
        height: Math.max(maxY - minY, 1e-6),
      });
    }
  }
  return result;
}
