export interface StrokeLineWidths {
  outer: number;
  gap: number;
}

export interface PixelOffset {
  x: number;
  y: number;
}

const kFontSizeCanvasHeightRatio = 0.1;
const kStrokeGapThreshold = 0.0001;

export function fontSizePixels(canvasHeight: number): number {
  return canvasHeight * kFontSizeCanvasHeightRatio;
}

export function strokeLineWidthsPixels(
  strokeWidth: number,
  strokeGap: number,
  fontSize: number,
): StrokeLineWidths {
  const hasGap = strokeGap > kStrokeGapThreshold;
  return {
    outer: (hasGap ? 2 * (strokeGap + strokeWidth) : strokeWidth) * fontSize,
    gap: hasGap ? 2 * strokeGap * fontSize : 0,
  };
}

export function shadowOffsetPixels(
  distance: number,
  angleDegrees: number,
  canvasWidth: number,
  canvasHeight: number,
): PixelOffset {
  const angleRadians = (angleDegrees * Math.PI) / 180;
  const distancePixels = distance * (Math.min(canvasWidth, canvasHeight) / 100);
  return {
    x: Math.cos(angleRadians) * distancePixels,
    y: Math.sin(angleRadians) * distancePixels,
  };
}
