import type { Rgba } from "../shared/sceneSchema";

export interface GradientBounds {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
}

export interface GradientLineParameters {
  angle: number;
  start: number;
  end: number;
}

export interface GradientLine {
  startX: number;
  startY: number;
  endX: number;
  endY: number;
}

export interface GradientBand {
  start: number;
  end: number;
  color: Rgba;
}

const kGradientBandCount = 4;
const kMinimumMidpoint = 0.000001;

export function computeGradientLine(
  bounds: GradientBounds,
  parameters: GradientLineParameters,
): GradientLine {
  const angleRadians = (parameters.angle * Math.PI) / 180;
  const centerX = (bounds.minX + bounds.maxX) / 2;
  const centerY = (bounds.minY + bounds.maxY) / 2;
  const directionX = Math.cos(angleRadians);
  const directionY = Math.sin(angleRadians);
  const cornerOffsets = [
    [bounds.minX - centerX, bounds.minY - centerY],
    [bounds.maxX - centerX, bounds.minY - centerY],
    [bounds.minX - centerX, bounds.maxY - centerY],
    [bounds.maxX - centerX, bounds.maxY - centerY],
  ] as const;
  const projections = cornerOffsets.map(
    ([offsetX, offsetY]) => offsetX * directionX + offsetY * directionY,
  );
  const minimumProjection = Math.min(...projections);
  const maximumProjection = Math.max(...projections);
  const boundingStartX = centerX + directionX * minimumProjection;
  const boundingStartY = centerY + directionY * minimumProjection;
  const boundingEndX = centerX + directionX * maximumProjection;
  const boundingEndY = centerY + directionY * maximumProjection;
  return {
    startX: interpolate(boundingStartX, boundingEndX, parameters.start),
    startY: interpolate(boundingStartY, boundingEndY, parameters.start),
    endX: interpolate(boundingStartX, boundingEndX, parameters.end),
    endY: interpolate(boundingStartY, boundingEndY, parameters.end),
  };
}

export function makeFourGradientBands(
  startColor: Rgba,
  endColor: Rgba,
  midpoint: number,
): GradientBand[] {
  const result: GradientBand[] = [];
  for (let index = 0; index < kGradientBandCount; index += 1) {
    const sample = index / (kGradientBandCount - 1);
    result.push({
      start: index / kGradientBandCount,
      end: (index + 1) / kGradientBandCount,
      color: interpolateColor(startColor, endColor, applyMidpoint(sample, midpoint)),
    });
  }
  return result;
}

function applyMidpoint(value: number, midpoint: number): number {
  const safeMidpoint = Math.min(Math.max(midpoint, kMinimumMidpoint), 1 - kMinimumMidpoint);
  let result: number;
  if (value <= safeMidpoint) {
    result = 0.5 * (value / safeMidpoint);
  } else {
    result = 0.5 + 0.5 * ((value - safeMidpoint) / (1 - safeMidpoint));
  }
  return result;
}

function interpolateColor(start: Rgba, end: Rgba, amount: number): Rgba {
  return {
    r: interpolate(start.r, end.r, amount),
    g: interpolate(start.g, end.g, amount),
    b: interpolate(start.b, end.b, amount),
    a: interpolate(start.a, end.a, amount),
  };
}

function interpolate(start: number, end: number, amount: number): number {
  return start + (end - start) * amount;
}
