// Minimal 2D affine matrix in canvas setTransform() order:
//   | a c e |
//   | b d f |
// Kept DOM-free so it is usable from plain-node tests.

export interface Mat2D {
  a: number;
  b: number;
  c: number;
  d: number;
  e: number;
  f: number;
}

export function identity(): Mat2D {
  return { a: 1, b: 0, c: 0, d: 1, e: 0, f: 0 };
}

export function multiply(left: Mat2D, right: Mat2D): Mat2D {
  return {
    a: left.a * right.a + left.c * right.b,
    b: left.b * right.a + left.d * right.b,
    c: left.a * right.c + left.c * right.d,
    d: left.b * right.c + left.d * right.d,
    e: left.a * right.e + left.c * right.f + left.e,
    f: left.b * right.e + left.d * right.f + left.f,
  };
}

export function invert(matrix: Mat2D): Mat2D | undefined {
  const determinant = matrix.a * matrix.d - matrix.b * matrix.c;
  let result: Mat2D | undefined;
  if (Math.abs(determinant) > Number.EPSILON) {
    result = {
      a: matrix.d / determinant,
      b: -matrix.b / determinant,
      c: -matrix.c / determinant,
      d: matrix.a / determinant,
      e: (matrix.c * matrix.f - matrix.d * matrix.e) / determinant,
      f: (matrix.b * matrix.e - matrix.a * matrix.f) / determinant,
    };
  }
  return result;
}

export function translation(x: number, y: number): Mat2D {
  return { a: 1, b: 0, c: 0, d: 1, e: x, f: y };
}

export function rotationDegrees(degrees: number): Mat2D {
  const radians = (degrees * Math.PI) / 180;
  const cos = Math.cos(radians);
  const sin = Math.sin(radians);
  return { a: cos, b: sin, c: -sin, d: cos, e: 0, f: 0 };
}

export function scaling(x: number, y: number): Mat2D {
  return { a: x, b: 0, c: 0, d: y, e: 0, f: 0 };
}

export function transformPoint(matrix: Mat2D, x: number, y: number): { x: number; y: number } {
  return {
    x: matrix.a * x + matrix.c * y + matrix.e,
    y: matrix.b * x + matrix.d * y + matrix.f,
  };
}

export interface AnchoredTransform {
  anchorX: number;
  anchorY: number;
  offsetX: number;
  offsetY: number;
  rotationDegrees: number;
  scaleX: number;
  scaleY: number;
}

// Offset translation combined with rotation and scale pivoting around an
// anchor point: T(offset) * T(anchor) * R * S * T(-anchor). Because T(anchor)
// and T(-anchor) cancel out under identity rotation/scale, moving the anchor
// alone never displaces the result — only offset does. This matches the host
// plugin's TransformHelper::getGlobalMatrix / getCharacterMatrix point flow:
// p -> T(-pivot) -> S(scale) -> R(rotation) -> T(pivot) -> T(offset).
export function composeAnchored(parameters: AnchoredTransform): Mat2D {
  let result = translation(parameters.offsetX, parameters.offsetY);
  result = multiply(result, translation(parameters.anchorX, parameters.anchorY));
  result = multiply(result, rotationDegrees(parameters.rotationDegrees));
  result = multiply(result, scaling(parameters.scaleX, parameters.scaleY));
  result = multiply(result, translation(-parameters.anchorX, -parameters.anchorY));
  return result;
}
